-- Let me check the equipmentutilizationpercent - could WRMI be related to some index?
-- Also let me see if there's a pattern with efficiencyindex or environmentalimpactindex
SELECT e.equipmentcode, e.equipmenttype, e.equipmentutilizationpercent, e.reliabilityindex, e.performanceindex, e.efficiencyindex, e.safetyindex, e.environmentalimpactindex FROM equipment e LIMIT 10;

-- Let me check how many location records exist and their relationship to waterandwaste
SELECT COUNT(*) as total_locations FROM location;
SELECT COUNT(*) as total_water_records FROM waterandwaste;

-- Let me understand the relationship between location and waterandwaste better
-- Check if every location has a corresponding waterandwaste record
SELECT COUNT(DISTINCT l.locationregistry) as total_locs, COUNT(w.waterregistry) as matched_water FROM location l LEFT JOIN waterandwaste w ON w.watereqref = l.loceqref;
